#include <cuda_runtime.h>
#include <vector>
#include <algorithm>
#define main original_unmodified_cli_main
#include "../murmurhash3-cuda/murmurhash3.cu"
#undef main
template<class T>std::vector<T>readfile(const char*name){FILE*f=fopen(name,"rb");if(!f)exit(2);fseek(f,0,SEEK_END);size_t n=ftell(f)/sizeof(T);rewind(f);std::vector<T>v(n);if(fread(v.data(),sizeof(T),n,f)!=n)exit(3);fclose(f);return v;}
int main(){auto keys=readfile<uint8_t>("keys_u8.bin");auto offsets=readfile<uint32_t>("offsets_u32.bin");auto lengths=readfile<uint32_t>("lengths_u32.bin");auto gold=readfile<uint64_t>("oracle_u64.bin");const int G=16,R=10;const uint8_t BG=0xa5;const uint32_t WG=0xa55a3cc3u;const uint64_t OG=0xcafebabedeadbeefULL;bool all=true;
 for(int trial=0;trial<=5;trial++){size_t bo=0,oo=0,lo=0,go=0;bool ok=true;int bad=0;std::vector<uint64_t>prefix,outputs;std::vector<double>times;
 for(int n:{257,4099})for(int fixture=0;fixture<2;fixture++){size_t bytes=offsets[oo+n];std::vector<uint8_t>kh(bytes+2*G,BG),ak(kh.size());std::copy_n(keys.data()+bo,bytes,kh.data()+G);std::vector<uint32_t>oh(n+1+2*G,WG),lh(n+2*G,WG),ao(oh.size()),al(lh.size());std::copy_n(offsets.data()+oo,n+1,oh.data()+G);std::copy_n(lengths.data()+lo,n,lh.data()+G);std::vector<uint64_t>initial(2*n+2*G,OG),before(initial.size()),answer(initial.size());uint8_t*dk;uint32_t*dof,*dl;uint64_t*out;cudaMalloc(&dk,kh.size());cudaMalloc(&dof,oh.size()*4);cudaMalloc(&dl,lh.size()*4);cudaMalloc(&out,initial.size()*8);cudaMemcpy(dk,kh.data(),kh.size(),cudaMemcpyHostToDevice);cudaMemcpy(dof,oh.data(),oh.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(dl,lh.data(),lh.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(out,initial.data(),initial.size()*8,cudaMemcpyHostToDevice);auto launch=[&](){MurmurHash3_x64_128_kernel<<<(n+255)/256,256>>>(dk+G,dof+G,dl+G,out+G,n);};if(trial==0){launch();ok &=cudaGetLastError()==cudaSuccess&&cudaDeviceSynchronize()==cudaSuccess;cudaFree(dk);cudaFree(dof);cudaFree(dl);cudaFree(out);bo+=bytes;oo+=n+1;lo+=n;go+=2*n;continue;}cudaMemcpy(before.data(),out,before.size()*8,cudaMemcpyDeviceToHost);ok &=before==initial;cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int rep=0;rep<R;rep++)launch();ok &=cudaGetLastError()==cudaSuccess&&cudaDeviceSynchronize()==cudaSuccess;times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/R);cudaMemcpy(ak.data(),dk,kh.size(),cudaMemcpyDeviceToHost);cudaMemcpy(ao.data(),dof,oh.size()*4,cudaMemcpyDeviceToHost);cudaMemcpy(al.data(),dl,lh.size()*4,cudaMemcpyDeviceToHost);cudaMemcpy(answer.data(),out,answer.size()*8,cudaMemcpyDeviceToHost);ok &=ak==kh&&ao==oh&&al==lh;for(int i=0;i<G;i++)bad+=answer[i]!=OG||answer[answer.size()-G+i]!=OG;for(int i=0;i<2*n;i++)bad+=answer[G+i]!=gold[go+i];ok &=answer[G]==0&&answer[G+1]==0;for(auto v:ak)prefix.push_back(v);for(auto v:ao)prefix.push_back(v);for(auto v:al)prefix.push_back(v);prefix.insert(prefix.end(),before.begin(),before.end());outputs.insert(outputs.end(),answer.begin(),answer.end());cudaFree(dk);cudaFree(dof);cudaFree(dl);cudaFree(out);bo+=bytes;oo+=n+1;lo+=n;go+=2*n;
 }if(!trial){if(!ok)return 4;continue;}ok &=bad==0;all &=ok;std::vector<uint64_t>artifact=prefix;artifact.insert(artifact.end(),outputs.begin(),outputs.end());char path[80];snprintf(path,80,"output_trial%d.bin",trial);FILE*f=fopen(path,"wb");if(!f)return 5;fwrite(artifact.data(),8,artifact.size(),f);fclose(f);double sum=0;for(double t:times)sum+=t;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"max_rel_error\":%s,\"timing_region\":\"sum4_hash_kernel_hostwindows_R10\",\"jit_excluded\":true,\"path_times_seconds\":[",trial,sum,ok?"true":"false",artifact.size(),bad?1:0,bad?"null":"0");for(size_t j=0;j<times.size();j++)printf("%s%.12g",j?",":"",times[j]);printf("],\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path,artifact.size());
 }puts(all?"PASS":"FAIL");return all?0:1;}
